def solve_small(N):
    max_m = 0
    # We can assume the sequence consists of blocks of 1, 2, ..., k
    # Let c_i be the size of the i-th block.
    # m = sum_{i=1}^{k-2} c_i * c_{i+1} * c_{i+2}
    # sum c_i = N

    # k can be up to N.
    import itertools

    def get_m(c):
        m = 0
        for i in range(len(c) - 2):
            m += c[i] * c[i+1] * c[i+2]
        return m

    # To find the partitions of N
    def partitions(n, k):
        if k == 1:
            yield (n,)
            return
        for i in range(1, n - k + 2):
            for p in partitions(n - i, k - 1):
                yield (i,) + p

    for k in range(3, N + 1):
        for c in partitions(N, k):
            max_m = max(max_m, get_m(c))
    return max_m

